DROP TABLE IF EXISTS `student_academic`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `student_academic` (
  `student_id` bigint(20) unsigned NOT NULL,
  `branch_id` bigint(20) unsigned DEFAULT NULL,
  `major_id` bigint(20) unsigned DEFAULT NULL,
  `academic_year_id` bigint(20) unsigned DEFAULT NULL,
  `result_type_id` bigint(20) unsigned DEFAULT NULL,
  `round_id` bigint(20) unsigned DEFAULT NULL,
  `total` int(10) unsigned NOT NULL DEFAULT 0,
  `average` decimal(10,2) NOT NULL DEFAULT 0.00,
  `round` varchar(255) NOT NULL DEFAULT '',
  `last_school` varchar(255) NOT NULL DEFAULT '',
  `middle_doc_number` varchar(255) NOT NULL DEFAULT '',
  `middle_doc_date` date DEFAULT NULL,
  `issuing_authority` varchar(255) NOT NULL DEFAULT '',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `updated_by` bigint(20) unsigned DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`student_id`),
  KEY `student_academic_major_id_foreign` (`major_id`),
  KEY `student_academic_academic_year_id_foreign` (`academic_year_id`),
  KEY `student_academic_result_type_id_foreign` (`result_type_id`),
  KEY `stu_acad_filter_idx` (`branch_id`,`major_id`,`academic_year_id`,`result_type_id`),
  KEY `student_academic_round_id_foreign` (`round_id`),
  KEY `student_academic_created_by_foreign` (`created_by`),
  KEY `student_academic_updated_by_foreign` (`updated_by`),
  CONSTRAINT `student_academic_academic_year_id_foreign` FOREIGN KEY (`academic_year_id`) REFERENCES `academic_years` (`id`) ON DELETE SET NULL,
  CONSTRAINT `student_academic_branch_id_foreign` FOREIGN KEY (`branch_id`) REFERENCES `branches` (`id`) ON DELETE SET NULL,
  CONSTRAINT `student_academic_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `student_academic_major_id_foreign` FOREIGN KEY (`major_id`) REFERENCES `majors` (`id`) ON DELETE SET NULL,
  CONSTRAINT `student_academic_result_type_id_foreign` FOREIGN KEY (`result_type_id`) REFERENCES `result_types` (`id`) ON DELETE SET NULL,
  CONSTRAINT `student_academic_round_id_foreign` FOREIGN KEY (`round_id`) REFERENCES `round_options` (`id`) ON DELETE SET NULL,
  CONSTRAINT `student_academic_student_id_foreign` FOREIGN KEY (`student_id`) REFERENCES `students` (`id`) ON DELETE CASCADE,
  CONSTRAINT `student_academic_updated_by_foreign` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

