DROP TABLE IF EXISTS `student_results_import_temp`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `student_results_import_temp` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `import_batch_id` varchar(64) NOT NULL,
  `row_index` int(10) unsigned NOT NULL,
  `student_id` bigint(20) unsigned DEFAULT NULL,
  `exam_number` varchar(255) DEFAULT NULL,
  `student_name` varchar(500) DEFAULT NULL,
  `branch` varchar(255) DEFAULT NULL,
  `major` varchar(255) DEFAULT NULL,
  `academic_year` varchar(64) DEFAULT NULL,
  `subjects_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`subjects_json`)),
  `total` varchar(255) DEFAULT NULL,
  `average` varchar(255) DEFAULT NULL,
  `result` varchar(255) DEFAULT NULL,
  `status` varchar(32) NOT NULL DEFAULT 'pending',
  `error` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `student_results_import_temp_import_batch_id_index` (`import_batch_id`)
) ENGINE=InnoDB AUTO_INCREMENT=35 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
